#!/usr/bin/env python3
"""Apply script: fix broken group_product_mapping test import + a
leftover stray schema fields discrepancy that came from an earlier,
stale apply script.

Background: your branch on GitHub had moved ahead with other commits
(from earlier in this same session) that my sandbox had not picked up
yet when I built the previous apply script, so it was based on a stale
copy. That previous script itself was fine (target premium + category
mapping both work), but it also carried 2 unrelated leftover fields in
schemas.py from that stale copy. This script removes those, and fixes
the real blocker: a test file importing a function
(parse_subgroup_master_mapping) from the wrong module, which is what
broke your pytest run.

Run from the HealthCross repo root: python3 apply_fix_group_product_mapping_test.py
"""
import base64, hashlib, os, sys

MARKER = "FIX_GROUP_PRODUCT_MAPPING_TEST_IMPORT_2026_08_04"

FILES = [
    {
        'path': 'app/models/schemas.py',
        'sha256': '18592177ff89c195ac564b35ca92243e3d19fae269ef201175dc6eac24c9dbb9',
        'size': 13038,
        'b64': '',
    },
    {
        'path': 'tests/test_ingestion_group_product_mapping.py',
        'sha256': 'c4cf794d7b63d19d0a315216c57f5fb6efa2b8b1604fcca5fbfb169ce57ed57d',
        'size': 2311,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 441 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
